package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.collaboration.assignment.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class AssignmentStoreIntegrationTest {
 StudyStoreIntegrationTest parent;GroupStoreIntegrationTest f;AssignmentStore store;UUID group,space,study;
 @BeforeEach void setup(){parent=new StudyStoreIntegrationTest();parent.setup();f=parent.f;group=parent.group;space=parent.space;study=parent.create(f.key()).study().studyId();store=new AssignmentStore(f.source,parent.store,Clock.systemUTC());}
 AssignmentStore.Result create(String key){return store.create(group,space,study,f.owner,key,"Assignment <script>","공유 지시문\n리터럴",f.trace);}
 void status(int code,org.junit.jupiter.api.function.Executable op){assertEquals(code,assertThrows(ResponseStatusException.class,op).getStatusCode().value());}
 int events(UUID id){return parent.events(id);}
 @Test void completeDefinitionRevisionAndEnvelopeCommitTogether()throws Exception{
  var v=create(f.key()).assignment();assertEquals(7,v.assignmentId().version());assertEquals("DRAFT",v.state());assertEquals("PRIVATE",v.visibility());assertEquals(study,v.studyId());assertEquals(v,store.get(group,space,study,v.assignmentId()));var h=store.history(group,space,study,v.assignmentId(),Long.MAX_VALUE,10);assertEquals(v,h.items().getFirst().snapshot());assertEquals(f.owner,h.items().getFirst().actorId());
  var e=AssignmentEnvelopeV1.parseFrom(f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.assignmentId()));var p=AssignmentSnapshotV1.parseFrom(e.getPayload());assertEquals("AssignmentCreated",e.getEventType());assertEquals("Assignment",e.getAggregateType());assertEquals(v.assignmentId().toString(),e.getAggregateId());assertEquals(space.toString(),e.getSpaceId());assertEquals(f.owner.toString(),e.getActorId());assertEquals(f.trace,e.getTraceId());assertEquals(study.toString(),p.getStudyId());assertEquals(group.toString(),p.getGroupId());assertEquals(v.description(),p.getDescription());assertEquals(v.createdAt(),p.getCreatedAt());assertEquals(1,p.getVersion());
 }
 @Test void originalCreationIntentReplaysCurrentStateAfterEditsArchivesAndRestart(){
  String key=f.key();var v=create(key).assignment();assertFalse(create(key).created());status(409,()->store.create(group,space,study,f.owner,key,"Changed","",f.trace));store.metadata(group,space,study,v.assignmentId(),f.owner,1,"Edited","",f.trace);var retired=store.state(group,space,study,v.assignmentId(),f.owner,2,"RETIRED",f.trace);parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);
  assertEquals(retired,new AssignmentStore(f.source,parent.store,Clock.systemUTC()).create(group,space,study,f.owner,key,v.title(),v.description(),f.trace).assignment());assertEquals(3,events(v.assignmentId()));status(409,()->create(f.key()));
 }
 @Test void lifecycleAndNoOpsUseAssignmentVersionWithoutChangingParent(){
  var v=create(f.key()).assignment();status(409,()->store.state(group,space,study,v.assignmentId(),f.owner,1,"CLOSED",f.trace));status(412,()->store.metadata(group,space,study,v.assignmentId(),f.owner,2,"Lost","",f.trace));assertEquals(v,store.metadata(group,space,study,v.assignmentId(),f.owner,1,v.title(),v.description(),f.trace));assertEquals(1,events(v.assignmentId()));
  var open=store.state(group,space,study,v.assignmentId(),f.owner,1,"OPEN",f.trace);assertEquals(open,store.state(group,space,study,v.assignmentId(),f.owner,2,"OPEN",f.trace));status(409,()->store.state(group,space,study,v.assignmentId(),f.owner,2,"DRAFT",f.trace));store.state(group,space,study,v.assignmentId(),f.owner,2,"CLOSED",f.trace);status(409,()->store.state(group,space,study,v.assignmentId(),f.owner,3,"OPEN",f.trace));store.metadata(group,space,study,v.assignmentId(),f.owner,3,"Corrected","",f.trace);var retired=store.state(group,space,study,v.assignmentId(),f.owner,4,"RETIRED",f.trace);assertEquals(retired,store.state(group,space,study,v.assignmentId(),f.owner,5,"RETIRED",f.trace));status(409,()->store.metadata(group,space,study,v.assignmentId(),f.owner,5,"Restore","",f.trace));assertEquals(5,events(v.assignmentId()));assertEquals(1,parent.store.get(group,space,study).version());
 }
 @Test void parentArchiveKeepsReadsAndHistoryButFreezesChanges(){
  var v=create(f.key()).assignment();parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);assertEquals(v,store.get(group,space,study,v.assignmentId()));assertEquals(1,store.list(group,space,study,null,20).items().size());assertEquals(1,store.history(group,space,study,v.assignmentId(),Long.MAX_VALUE,10).items().size());status(409,()->store.metadata(group,space,study,v.assignmentId(),f.owner,1,"Changed","",f.trace));status(409,()->store.state(group,space,study,v.assignmentId(),f.owner,1,"OPEN",f.trace));status(409,()->create(f.key()));assertEquals(1,events(v.assignmentId()));
 }
 @Test void concurrentRetryAndEditsProduceOneWinner()throws Exception{
  String key=f.key();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return create(key);});var b=pool.submit(()->{barrier.await();return create(key);});var x=a.get();var y=b.get();assertNotEquals(x.created(),y.created());assertEquals(x.assignment(),y.assignment());assertEquals(1,events(x.assignment().assignmentId()));var results=new ArrayList<Future<Boolean>>();for(String title:List.of("A","B"))results.add(pool.submit(()->{barrier.await();try{store.metadata(group,space,study,x.assignment().assignmentId(),f.owner,1,title,"",f.trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(results.get(0).get(),results.get(1).get());assertEquals(2,events(x.assignment().assignmentId()));}
 }
 @Test void studyArchiveAndChildWriteSerializeOnSameParentLock()throws Exception{
  var v=create(f.key()).assignment();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return parent.store.state(group,space,study,f.owner,1,"RETIRED",f.trace);});var b=pool.submit(()->{barrier.await();try{return store.state(group,space,study,v.assignmentId(),f.owner,1,"OPEN",f.trace);}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals("RETIRED",a.get().state());var result=b.get();assertEquals(result==null?1:2,events(v.assignmentId()));status(409,()->store.metadata(group,space,study,v.assignmentId(),f.owner,result==null?1:2,"After archive","",f.trace));}
 }
 @Test void failedOutboxRollsBackCreationAndExistingSnapshotRevision(){
  String constraint="assignment_fail_"+study.toString().replace("-","");String check=" CHECK (aggregatetype <> 'assignment' OR trace_id <> '"+f.trace+"') NOT VALID";f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+check);
  try{assertThrows(RuntimeException.class,()->create(f.key()));assertTrue(store.list(group,space,study,null,20).items().isEmpty());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}
  var v=create(f.key()).assignment();f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+check);try{assertThrows(RuntimeException.class,()->store.state(group,space,study,v.assignmentId(),f.owner,1,"OPEN",f.trace));assertEquals(v,store.get(group,space,study,v.assignmentId()));assertEquals(1,events(v.assignmentId()));assertEquals(1,store.history(group,space,study,v.assignmentId(),Long.MAX_VALUE,10).items().size());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}
 }
 @Test void catalogAndHistoryStayScopedToExactStudyGroupAndSpace(){
  var a=create(f.key()).assignment();create(f.key());create(f.key());var page=store.list(group,space,study,null,2);assertEquals(2,page.items().size());assertNotNull(page.nextAfter());assertEquals(1,store.list(group,space,study,page.nextAfter(),2).items().size());UUID other=parent.create(f.key()).study().studyId();assertTrue(store.list(group,space,other,null,20).items().isEmpty());status(404,()->store.get(group,space,other,a.assignmentId()));status(404,()->store.history(group,space,other,a.assignmentId(),Long.MAX_VALUE,5));status(404,()->store.get(group,f.owner,study,a.assignmentId()));status(404,()->store.get(f.owner,space,study,a.assignmentId()));status(404,()->store.create(group,space,f.owner,f.owner,f.key(),"Wrong study","",f.trace));
  store.metadata(group,space,study,a.assignmentId(),f.owner,1,"v2","",f.trace);store.metadata(group,space,study,a.assignmentId(),f.owner,2,"v3","",f.trace);var h=store.history(group,space,study,a.assignmentId(),Long.MAX_VALUE,2);assertEquals(List.of(3L,2L),h.items().stream().map(AssignmentStore.Revision::version).toList());assertEquals(2L,h.nextBefore());assertEquals(1,store.history(group,space,study,a.assignmentId(),h.nextBefore(),2).items().size());
 }
}
